// Ports of the OpenCV / scipy primitives oemer relies on, matched against golden outputs
// (tests/fixtures/omr/golden-primitives.json, generated by tools/omr_golden.py).

/** Binary or small-integer raster, row-major. */
export interface Raster {
  width: number;
  height: number;
  data: Uint8Array;
}

export type BBox = [number, number, number, number]; // x1, y1, x2, y2 (x2/y2 exclusive, like oemer)

export function raster(width: number, height: number, data?: Uint8Array): Raster {
  return { width, height, data: data ?? new Uint8Array(width * height) };
}

/** C/C++ lrint-style rounding (half to even), as cvRound does. */
export function cvRound(v: number): number {
  const f = Math.floor(v);
  const d = v - f;
  if (d > 0.5) return f + 1;
  if (d < 0.5) return f;
  return f % 2 === 0 ? f : f + 1;
}

// ------------------------------------------------------------------ scipy.signal.find_peaks

export interface PeakOptions {
  height?: number;
  distance?: number;
  prominence?: number;
}

/** scipy.signal.find_peaks for the options oemer uses (height, distance, prominence). */
export function findPeaks(x: ArrayLike<number>, opts: PeakOptions = {}): number[] {
  const n = x.length;
  // local maxima, plateaus resolved to their midpoint (scipy _local_maxima_1d)
  let peaks: number[] = [];
  let i = 1;
  const iMax = n - 1;
  while (i < iMax) {
    if (x[i - 1] < x[i]) {
      let ahead = i + 1;
      while (ahead < iMax && x[ahead] === x[i]) ahead++;
      if (x[ahead] < x[i]) {
        peaks.push(Math.floor((i + ahead - 1) / 2));
        i = ahead;
      }
    }
    i++;
  }
  if (opts.height !== undefined) peaks = peaks.filter((p) => x[p] >= opts.height!);
  if (opts.distance !== undefined && opts.distance > 1 && peaks.length > 1) {
    const distance = Math.ceil(opts.distance);
    const keep = new Array<boolean>(peaks.length).fill(true);
    // highest first; ties: later index first (numpy argsort is ascending, iterated from the end)
    const order = peaks.map((_, k) => k).sort((a, b) => x[peaks[a]] - x[peaks[b]] || a - b);
    for (let o = order.length - 1; o >= 0; o--) {
      const j = order[o];
      if (!keep[j]) continue;
      let k = j - 1;
      while (k >= 0 && peaks[j] - peaks[k] < distance) keep[k--] = false;
      k = j + 1;
      while (k < peaks.length && peaks[k] - peaks[j] < distance) keep[k++] = false;
    }
    peaks = peaks.filter((_, k) => keep[k]);
  }
  if (opts.prominence !== undefined) {
    peaks = peaks.filter((p) => prominence(x, p) >= opts.prominence!);
  }
  return peaks;
}

/** scipy _peak_prominences without a window. */
export function prominence(x: ArrayLike<number>, p: number): number {
  let leftMin = x[p];
  for (let i = p; i >= 0 && x[i] <= x[p]; i--) if (x[i] < leftMin) leftMin = x[i];
  let rightMin = x[p];
  for (let i = p; i < x.length && x[i] <= x[p]; i++) if (x[i] < rightMin) rightMin = x[i];
  return x[p] - Math.max(leftMin, rightMin);
}

// ------------------------------------------------------------------ regression

/** Slope of the least-squares line y = a·x + b (sklearn LinearRegression().coef_[0]). */
export function olsSlope(xs: ArrayLike<number>, ys: ArrayLike<number>): number {
  const n = xs.length;
  let mx = 0;
  let my = 0;
  for (let i = 0; i < n; i++) {
    mx += xs[i];
    my += ys[i];
  }
  mx /= n;
  my /= n;
  let sxy = 0;
  let sxx = 0;
  for (let i = 0; i < n; i++) {
    const dx = xs[i] - mx;
    sxy += dx * (ys[i] - my);
    sxx += dx * dx;
  }
  return sxx === 0 ? 0 : sxy / sxx;
}

// ------------------------------------------------------------------ morphology

/** Structuring element as a rows×cols 0/1 matrix. */
export interface Kernel {
  rows: number;
  cols: number;
  data: Uint8Array;
}

export function rectKernel(rows: number, cols: number): Kernel {
  return { rows, cols, data: new Uint8Array(rows * cols).fill(1) };
}

/** cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (width, height)). */
export function ellipseKernel(width: number, height: number): Kernel {
  const data = new Uint8Array(width * height);
  const r = Math.floor(height / 2);
  const c = Math.floor(width / 2);
  const invR2 = r ? 1 / (r * r) : 0;
  for (let i = 0; i < height; i++) {
    let j1 = 0;
    let j2 = 0;
    const dy = i - r;
    if (Math.abs(dy) <= r) {
      const dx = cvRound(c * Math.sqrt((r * r - dy * dy) * invR2));
      j1 = Math.max(c - dx, 0);
      j2 = Math.min(c + dx + 1, width);
    }
    for (let j = j1; j < j2; j++) data[i * width + j] = 1;
  }
  return { rows: height, cols: width, data };
}

function morph(src: Raster, k: Kernel, isErode: boolean): Raster {
  const { width: w, height: h, data: s } = src;
  const out = new Uint8Array(w * h);
  const ax = Math.floor(k.cols / 2);
  const ay = Math.floor(k.rows / 2);
  const offs: [number, number][] = [];
  for (let ky = 0; ky < k.rows; ky++) for (let kx = 0; kx < k.cols; kx++) if (k.data[ky * k.cols + kx]) offs.push([kx - ax, ky - ay]);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let v = isErode ? 255 : 0;
      for (const [dx, dy] of offs) {
        const xx = x + dx;
        const yy = y + dy;
        if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue; // border ignored (OpenCV default)
        const p = s[yy * w + xx];
        if (isErode ? p < v : p > v) v = p;
      }
      out[y * w + x] = v;
    }
  }
  return { width: w, height: h, data: out };
}

export const erode = (src: Raster, k: Kernel): Raster => morph(src, k, true);
export const dilate = (src: Raster, k: Kernel): Raster => morph(src, k, false);
export const morphOpen = (src: Raster, k: Kernel): Raster => dilate(erode(src, k), k);
export const morphClose = (src: Raster, k: Kernel): Raster => erode(dilate(src, k), k);

// ------------------------------------------------------------------ connected components

/** scipy.ndimage.label with the default 4-connected structure. Labels follow raster order. */
export function label4(src: Raster): { labels: Int32Array; count: number } {
  const { width: w, height: h, data } = src;
  const labels = new Int32Array(w * h);
  const parent: number[] = [0];
  const find = (a: number): number => {
    while (parent[a] !== a) {
      parent[a] = parent[parent[a]];
      a = parent[a];
    }
    return a;
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (!data[i]) continue;
      const up = y > 0 ? labels[i - w] : 0;
      const left = x > 0 ? labels[i - 1] : 0;
      if (!up && !left) {
        parent.push(parent.length);
        labels[i] = parent.length - 1;
      } else if (up && left) {
        const a = find(up);
        const b = find(left);
        labels[i] = Math.min(a, b);
        if (a !== b) parent[Math.max(a, b)] = Math.min(a, b);
      } else labels[i] = up || left;
    }
  }
  const remap = new Int32Array(parent.length);
  let count = 0;
  for (let i = 0; i < labels.length; i++) {
    if (!labels[i]) continue;
    const r = find(labels[i]);
    if (!remap[r]) remap[r] = ++count;
    labels[i] = remap[r];
  }
  return { labels, count };
}

// ------------------------------------------------------------------ findContours (RETR_TREE) → bounding boxes

interface ContourNode {
  box: BBox;
  hole: boolean;
  children: ContourNode[];
  parent: ContourNode | null;
}

// 8-neighbourhood in clockwise order starting East (y down): E, SE, S, SW, W, NW, N, NE
const DX = [1, 1, 0, -1, -1, -1, 0, 1];
const DY = [0, 1, 1, 1, 0, -1, -1, -1];

/**
 * Bounding boxes of all contours (outer borders and holes) in the order cv2.findContours(RETR_TREE)
 * returns them. Suzuki–Abe border following; boxes are [x1, y1, x2, y2] with exclusive x2/y2.
 */
export function findContourBoxes(src: Raster): BBox[] {
  const W = src.width + 2;
  const H = src.height + 2;
  const f = new Int32Array(W * H);
  for (let y = 0; y < src.height; y++) for (let x = 0; x < src.width; x++) if (src.data[y * src.width + x]) f[(y + 1) * W + x + 1] = 1;
  const root: ContourNode = { box: [0, 0, 0, 0], hole: true, children: [], parent: null };
  const nodes = new Map<number, ContourNode>([[1, root]]);
  let nbd = 1;
  const dirOf = (fromX: number, fromY: number, cx: number, cy: number) => {
    for (let d = 0; d < 8; d++) if (cx + DX[d] === fromX && cy + DY[d] === fromY) return d;
    return 0;
  };
  for (let i = 1; i < H - 1; i++) {
    let lnbd = 1;
    for (let j = 1; j < W - 1; j++) {
      const p = i * W + j;
      const v = f[p];
      let start = false;
      let hole = false;
      let i2 = 0;
      let j2 = 0;
      if (v === 1 && f[p - 1] === 0) {
        start = true;
        i2 = i;
        j2 = j - 1;
      } else if (v >= 1 && f[p + 1] === 0) {
        start = true;
        hole = true;
        i2 = i;
        j2 = j + 1;
        if (v > 1) lnbd = v;
      }
      if (start) {
        nbd++;
        const prev = nodes.get(Math.abs(lnbd)) ?? root;
        // parent rule (Suzuki & Abe, table 1)
        const parentNode = hole === prev.hole ? prev.parent ?? root : prev;
        let minX = j;
        let maxX = j;
        let minY = i;
        let maxY = i;
        // 3.1 clockwise search around (i, j) from (i2, j2) for a non-zero pixel
        let d0 = dirOf(j2, i2, j, i);
        let found = -1;
        for (let k = 0; k < 8; k++) {
          const d = (d0 + k) % 8;
          if (f[(i + DY[d]) * W + j + DX[d]]) {
            found = d;
            break;
          }
        }
        if (found < 0) {
          f[p] = -nbd;
        } else {
          const i1 = i + DY[found];
          const j1 = j + DX[found];
          let pi2 = i1;
          let pj2 = j1;
          let i3 = i;
          let j3 = j;
          for (;;) {
            // 3.3 counter-clockwise search around (i3, j3), starting after (pi2, pj2)
            d0 = dirOf(pj2, pi2, j3, i3);
            let i4 = 0;
            let j4 = 0;
            let eastZeroExamined = false;
            for (let k = 1; k <= 8; k++) {
              const d = (d0 - k + 16) % 8;
              const yy = i3 + DY[d];
              const xx = j3 + DX[d];
              if (f[yy * W + xx]) {
                i4 = yy;
                j4 = xx;
                break;
              }
              if (d === 0) eastZeroExamined = true;
            }
            const q = i3 * W + j3;
            if (eastZeroExamined) f[q] = -nbd;
            else if (f[q] === 1) f[q] = nbd;
            if (j3 < minX) minX = j3;
            if (j3 > maxX) maxX = j3;
            if (i3 < minY) minY = i3;
            if (i3 > maxY) maxY = i3;
            if (i4 === i && j4 === j && i3 === i1 && j3 === j1) break;
            pi2 = i3;
            pj2 = j3;
            i3 = i4;
            j3 = j4;
          }
        }
        const node: ContourNode = { box: [minX - 1, minY - 1, maxX, maxY], hole, children: [], parent: parentNode };
        parentNode.children.unshift(node); // OpenCV prepends new contours to the parent's child list
        nodes.set(nbd, node);
      }
      const cur = f[p];
      if (cur !== 1 && cur !== 0) lnbd = Math.abs(cur);
    }
  }
  const out: BBox[] = [];
  const walk = (n: ContourNode) => {
    for (const c of n.children) {
      out.push(c.box);
      walk(c);
    }
  };
  walk(root);
  return out;
}

// ------------------------------------------------------------------ HoughLinesP

/** cv::RNG (multiply-with-carry), seeded like HoughLinesP: RNG((uint64)-1). */
class CvRng {
  private state = 0xffffffffffffffffn;
  next(): number {
    this.state = ((this.state & 0xffffffffn) * 4164903690n + (this.state >> 32n)) & 0xffffffffffffffffn;
    return Number(this.state & 0xffffffffn);
  }
  uniform(a: number, b: number): number {
    return a === b ? a : (this.next() % (b - a)) + a;
  }
}

const f32 = Math.fround;

/** cv2.HoughLinesP(img, rho, theta, threshold, None, minLineLength, maxLineGap) → [x1, y1, x2, y2][]. */
export function houghLinesP(src: Raster, rho: number, theta: number, threshold: number, lineLength: number, lineGap: number): [number, number, number, number][] {
  const width = src.width;
  const height = src.height;
  const irho = 1 / rho;
  const rng = new CvRng();
  let numangle = Math.floor(Math.PI / theta) + 1;
  if (numangle > 1 && Math.abs(Math.PI - (numangle - 1) * theta) < theta / 2) numangle--;
  const numrho = cvRound(((width + height) * 2 + 1) / rho);
  const accum = new Int32Array(numangle * numrho);
  const mask = new Uint8Array(width * height);
  const ttab = new Float32Array(numangle * 2);
  for (let n = 0; n < numangle; n++) {
    ttab[n * 2] = f32(Math.cos(n * theta) * irho);
    ttab[n * 2 + 1] = f32(Math.sin(n * theta) * irho);
  }
  const nz: number[] = [];
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++)
      if (src.data[y * width + x]) {
        mask[y * width + x] = 1;
        nz.push(y * width + x);
      }
  const rIndex = (x: number, y: number, n: number) => cvRound(f32(f32(x * ttab[n * 2]) + f32(y * ttab[n * 2 + 1]))) + Math.floor((numrho - 1) / 2);
  const lines: [number, number, number, number][] = [];
  const shift = 16;
  for (let count = nz.length; count > 0; count--) {
    const idx = rng.uniform(0, count);
    let maxVal = threshold - 1;
    let maxN = 0;
    const pt = nz[idx];
    const i = Math.floor(pt / width);
    const j = pt - i * width;
    nz[idx] = nz[count - 1];
    if (!mask[i * width + j]) continue;
    for (let n = 0; n < numangle; n++) {
      const v = ++accum[n * numrho + rIndex(j, i, n)];
      if (maxVal < v) {
        maxVal = v;
        maxN = n;
      }
    }
    if (maxVal < threshold) continue;
    const a = f32(-ttab[maxN * 2 + 1]);
    const b = ttab[maxN * 2];
    let x0 = j;
    let y0 = i;
    let dx0: number;
    let dy0: number;
    let xflag: boolean;
    if (Math.abs(a) > Math.abs(b)) {
      xflag = true;
      dx0 = a > 0 ? 1 : -1;
      dy0 = cvRound(f32(f32(b * (1 << shift)) / Math.abs(a)));
      y0 = (y0 << shift) + (1 << (shift - 1));
    } else {
      xflag = false;
      dy0 = b > 0 ? 1 : -1;
      dx0 = cvRound(f32(f32(a * (1 << shift)) / Math.abs(b)));
      x0 = (x0 << shift) + (1 << (shift - 1));
    }
    const end: [number, number][] = [
      [0, 0],
      [0, 0],
    ];
    for (let k = 0; k < 2; k++) {
      let gap = 0;
      let x = x0;
      let y = y0;
      const dx = k ? -dx0 : dx0;
      const dy = k ? -dy0 : dy0;
      for (; ; x += dx, y += dy) {
        const j1 = xflag ? x : x >> shift;
        const i1 = xflag ? y >> shift : y;
        if (j1 < 0 || j1 >= width || i1 < 0 || i1 >= height) break;
        if (mask[i1 * width + j1]) {
          gap = 0;
          end[k] = [j1, i1];
        } else if (++gap > lineGap) break;
      }
    }
    const good = Math.abs(end[1][0] - end[0][0]) >= lineLength || Math.abs(end[1][1] - end[0][1]) >= lineLength;
    for (let k = 0; k < 2; k++) {
      let x = x0;
      let y = y0;
      const dx = k ? -dx0 : dx0;
      const dy = k ? -dy0 : dy0;
      for (; ; x += dx, y += dy) {
        const j1 = xflag ? x : x >> shift;
        const i1 = xflag ? y >> shift : y;
        const m = i1 * width + j1;
        if (mask[m]) {
          if (good) for (let n = 0; n < numangle; n++) accum[n * numrho + rIndex(j1, i1, n)]--;
          mask[m] = 0;
        }
        if (i1 === end[k][1] && j1 === end[k][0]) break;
      }
    }
    if (good) lines.push([end[0][0], end[0][1], end[1][0], end[1][1]]);
  }
  return lines;
}
